Object.assign(SNIP,{});PRESET_NOTES["l65"]={"Ví dụ: Thử chia tới căn n": "91 = 7 · 13 nên dừng ở i = 7. Với 1000000007 vòng lặp chạy tới khoảng 31623 rồi kết luận nguyên tố — thay vì một tỉ lần nếu thử tới n.", "Ví dụ: Sàng Eratosthenes": "Vòng ngoài chỉ chạy i = 2, 3, 5 (vì 6 · 6 > 30). 4 bị bỏ qua vì đã bị gạch. Còn lại 10 số nguyên tố.", "Ví dụ: Phân tích thừa số nguyên tố": "Mỗi lần tách được p thì n nhỏ lại nên điều kiện p · p ≤ n cũng co lại. Sau vòng lặp, nếu n > 1 thì phần còn lại chắc chắn nguyên tố (vì không có ước nào ≤ √n).", "Ví dụ: Sàng ước nguyên tố nhỏ nhất": "Dựng một lần O(N log log N), sau đó phân tích mỗi số chỉ vài phép chia — hợp khi cần phân tích rất nhiều số ≤ N.", "Lỗi: quên trường hợp n < 2": "In 6: với 0 và 1 vòng lặp không chạy lần nào nên hàm trả về true. Số nguyên tố bắt đầu từ 2; luôn xử lý riêng n < 2."};EX_HINTS["l65"]=[["Sàng Eratosthenes một lần tới r lớn nhất (≤ 10^5).", "pre[x] = số số nguyên tố ≤ x; đáp án pre[r] − pre[l − 1].", "Kiểm tra từng số trong đoạn bằng thử chia cho mỗi câu hỏi là quá chậm khi q và đoạn đều lớn."], ["Đảo câu hỏi: thay vì “x có những ước nào”, hỏi “d là ước của những số nào” — mọi bội của d.", "Hai vòng lặp: d từ 1 tới n, j = d, 2d, 3d, … ≤ n, tăng c[j]. Tổng số bước n/1 + n/2 + … ≈ n ln n.", "Đếm ước từng số bằng thử chia tới √x tốn khoảng n√n."], ["Cách 1: thử chia p = 2, 3, … khi p · p ≤ a; chia hết thì in p và chia a cho p (lặp while). Cuối cùng a > 1 thì in a.", "Cách 2 (khi có rất nhiều số): sàng spf (ước nguyên tố nhỏ nhất) tới 10^6 một lần, rồi lặp a /= spf[a]. Trên máy thật nhanh hơn; trong trình mô phỏng, dựng sàng 10^6 ô thì quá lâu nên dùng cách 1.", "Cẩn thận dấu cách thừa cuối dòng: chỉ in khoảng trắng giữa các số."]];
/* ===================== BÀI 65 · Số nguyên tố và sàng Eratosthenes ===================== */
/* Bài 65 · Số nguyên tố và sàng Eratosthenes
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR65=[{label:"Ví dụ: Thử chia tới căn n",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nbool laNguyenTo(long long n) {\n    if (n < 2) return false;\n    for (long long i = 2; i * i <= n; i++)   // chỉ cần thử tới √n\n        if (n % i == 0) return false;\n    return true;\n}\n\nint main() {\n    long long ds[] = {1, 2, 9, 17, 91, 97, 1000000007};\n    for (long long x : ds) cout << x << (laNguyenTo(x) ? \" nguyen to\" : \" hop so / khong\") << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","i"]}],py:{code:"def la_nguyen_to(n):\n    if n < 2:\n        return False\n    i = 2\n    while i * i <= n:                  # chỉ cần thử tới √n\n        if n % i == 0:\n            return False\n        i += 1\n    return True\n\nfor x in [1, 2, 9, 17, 91, 97, 1000000007]:\n    print(x, \"nguyen to\" if la_nguyen_to(x) else \"hop so / khong\")"},cs:{code:"using System;\n\nclass Program\n{\n    static bool LaNguyenTo(long n)\n    {\n        if (n < 2) return false;\n        for (long i = 2; i * i <= n; i++)  // chỉ cần thử tới √n\n            if (n % i == 0) return false;\n        return true;\n    }\n\n    static void Main()\n    {\n        long[] ds = { 1, 2, 9, 17, 91, 97, 1000000007 };\n        foreach (long x in ds) Console.WriteLine(x + (LaNguyenTo(x) ? \" nguyen to\" : \" hop so / khong\"));\n    }\n}"}},{label:"Ví dụ: Sàng Eratosthenes",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 30;\n    vector<bool> nt(n + 1, true);\n    nt[0] = nt[1] = false;\n    for (int i = 2; i * i <= n; i++)\n        if (nt[i])\n            for (int j = i * i; j <= n; j += i) nt[j] = false;   // gạch bội của i\n    for (int i = 2; i <= n; i++)\n        if (nt[i]) cout << i << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"nt",ptr:["i","j"]}],py:{code:"n = 30\nnt = [True] * (n + 1)\nnt[0] = nt[1] = False\ni = 2\nwhile i * i <= n:\n    if nt[i]:\n        for j in range(i * i, n + 1, i):   # gạch bội của i\n            nt[j] = False\n    i += 1\nprint(*[i for i in range(2, n + 1) if nt[i]])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 30;\n        bool[] nt = new bool[n + 1];\n        for (int i = 2; i <= n; i++) nt[i] = true;\n        for (int i = 2; i * i <= n; i++)\n            if (nt[i])\n                for (int j = i * i; j <= n; j += i) nt[j] = false;   // gạch bội của i\n        for (int i = 2; i <= n; i++)\n            if (nt[i]) Console.Write(i + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Phân tích thừa số nguyên tố",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    long long ds[] = {360, 97, 1001, 1024};\n    for (long long n : ds) {\n        cout << n << \" =\";\n        for (long long p = 2; p * p <= n; p++)\n            while (n % p == 0) { cout << \" \" << p; n /= p; }   // chia hết thì tách p ra\n        if (n > 1) cout << \" \" << n;  // phần còn lại là một số nguyên tố lớn\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"vars",names:["n","p"]}],py:{code:"for n in [360, 97, 1001, 1024]:\n    goc = n\n    ts = []\n    p = 2\n    while p * p <= n:\n        while n % p == 0:              # chia hết thì tách p ra\n            ts.append(p)\n            n //= p\n        p += 1\n    if n > 1:                          # phần còn lại là một số nguyên tố lớn\n        ts.append(n)\n    print(goc, \"=\", *ts)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long[] ds = { 360, 97, 1001, 1024 };\n        foreach (long x in ds)\n        {\n            long n = x;\n            Console.Write(n + \" =\");\n            for (long p = 2; p * p <= n; p++)\n                while (n % p == 0) { Console.Write(\" \" + p); n /= p; }   // chia hết thì tách p ra\n            if (n > 1) Console.Write(\" \" + n); // phần còn lại là một số nguyên tố lớn\n            Console.WriteLine();\n        }\n    }\n}"}},{label:"Ví dụ: Sàng ước nguyên tố nhỏ nhất",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int N = 60;\n    vector<int> spf(N + 1, 0);         // spf[x]: ước nguyên tố nhỏ nhất của x\n    for (int i = 2; i <= N; i++)\n        if (spf[i] == 0)               // i chưa bị ai gạch: nguyên tố\n            for (int j = i; j <= N; j += i)\n                if (spf[j] == 0) spf[j] = i;\n    int ds[] = {60, 49, 59};\n    for (int x : ds) {\n        cout << x << \":\";\n        while (x > 1) { cout << \" \" << spf[x]; x /= spf[x]; }   // O(log x) bước\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"spf",ptr:["i","j"]}],py:{code:"N = 60\nspf = [0] * (N + 1)                    # spf[x]: ước nguyên tố nhỏ nhất của x\nfor i in range(2, N + 1):\n    if spf[i] == 0:                    # i chưa bị ai gạch: nguyên tố\n        for j in range(i, N + 1, i):\n            if spf[j] == 0:\n                spf[j] = i\nfor x in [60, 49, 59]:\n    goc = x\n    ts = []\n    while x > 1:                       # O(log x) bước\n        ts.append(spf[x])\n        x //= spf[x]\n    print(str(goc) + \":\", *ts)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int N = 60;\n        int[] spf = new int[N + 1];            // spf[x]: ước nguyên tố nhỏ nhất của x\n        for (int i = 2; i <= N; i++)\n            if (spf[i] == 0)                   // i chưa bị ai gạch: nguyên tố\n                for (int j = i; j <= N; j += i)\n                    if (spf[j] == 0) spf[j] = i;\n        int[] ds = { 60, 49, 59 };\n        foreach (int goc in ds)\n        {\n            int x = goc;\n            Console.Write(x + \":\");\n            while (x > 1) { Console.Write(\" \" + spf[x]); x /= spf[x]; }   // O(log x) bước\n            Console.WriteLine();\n        }\n    }\n}"}},{label:"Lỗi: quên trường hợp n < 2",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nbool laNguyenTo(int n) {\n    for (int i = 2; i * i <= n; i++)   // SAI: thiếu if (n < 2) return false;\n        if (n % i == 0) return false;\n    return true;\n}\n\nint main() {\n    int dem = 0;\n    for (int x = 0; x <= 10; x++)\n        if (laNguyenTo(x)) dem++;\n    cout << dem << \"\\n\";               // đúng phải là 4 (2, 3, 5, 7)\n    return 0;\n}",viz:[{type:"vars",names:["x","n","i","dem"]}],py:{code:"def la_nguyen_to(n):\n    i = 2\n    while i * i <= n:                  # SAI: thiếu if n < 2: return False\n        if n % i == 0:\n            return False\n        i += 1\n    return True\n\ndem = 0\nfor x in range(11):\n    if la_nguyen_to(x):\n        dem += 1\nprint(dem)                             # đúng phải là 4 (2, 3, 5, 7)"},cs:{code:"using System;\n\nclass Program\n{\n    static bool LaNguyenTo(int n)\n    {\n        for (int i = 2; i * i <= n; i++)   // SAI: thiếu if (n < 2) return false;\n            if (n % i == 0) return false;\n        return true;\n    }\n\n    static void Main()\n    {\n        int dem = 0;\n        for (int x = 0; x <= 10; x++)\n            if (LaNguyenTo(x)) dem++;\n        Console.WriteLine(dem);                // đúng phải là 4 (2, 3, 5, 7)\n    }\n}"}}];
