makeEx2(document.getElementById("ex-l65"),sim65,[{t:"Đếm số nguyên tố trên đoạn",d:"Có q câu hỏi, mỗi câu “l r”: có bao nhiêu số nguyên tố trong [l, r]? Đầu vào: q (q ≤ 2·10^5) rồi q dòng l r (1 ≤ l ≤ r ≤ 10^5). Đầu ra: q dòng.",tests:[{in:"6\n1 10\n1 1\n2 2\n11 30\n14 16\n1 100",out:"4\n0\n1\n6\n0\n25"},{in:"1\n1 100000",out:"9592"},{in:"2\n99990 100000\n1 2",out:"1\n1"},{in:"30\n3398 3989\n2357 4463\n1802 3619\n3756 4838\n3630 4758\n2777 4564\n1848 2142\n4596 4835\n2164 2970\n3878 3971\n2105 2567\n1305 3469\n1109 4376\n1022 1583\n2872 4377\n4727 4914\n1890 4491\n1865 3495\n3684 4658\n410 1662\n171 2910\n2051 3359\n2217 2250\n1409 4426\n3524 3674\n2135 4376\n77 1571\n1327 3673\n4408 4851\n3524 3793",out:"72\n258\n227\n128\n133\n215\n40\n29\n102\n12\n58\n274\n412\n78\n181\n19\n319\n204\n116\n180\n382\n164\n4\n380\n22\n276\n227\n297\n51\n36"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int q;\n    cin >> q;\n    // đọc hết câu hỏi để biết r lớn nhất, sàng một lần, rồi dùng tổng tiền tố\n    for (int k = 0; k < q; k++) {\n        int l, r;\n        cin >> l >> r;\n        cout << 0 << \"\\n\";\n    }\n    return 0;\n}",perf:{gen:n=>{const q=[];for(let i=0;i<n;i++){const l=1+(i*7)%n;q.push(l+" "+(l+n))}return n+"\n"+q.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+300,why:"Thử chia từng số trong đoạn cho mỗi câu hỏi tốn O(độ dài · √r) mỗi câu."},py:{start:"q = int(input())\n# đọc hết câu hỏi để biết r lớn nhất, sàng một lần, rồi dùng tổng tiền tố\nout = []\nfor _ in range(q):\n    l, r = map(int, input().split())\n    out.append(0)\nprint(\"\\n\".join(map(str, out)))",hints:["Sàng Eratosthenes một lần tới r lớn nhất (≤ 10^5).","pre[x] = số số nguyên tố ≤ x (True cộng như 1); đáp án pre[r] − pre[l − 1].","Mẹo Python: nt[i*i::i] = [False] * số phần tử, gạch cả dãy bội trong một lệnh."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int q = int.Parse(Console.ReadLine());\n        // đọc hết câu hỏi để biết r lớn nhất, sàng một lần, rồi dùng tổng tiền tố\n        var sb = new StringBuilder();\n        for (int k = 0; k < q; k++)\n        {\n            int[] c = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            sb.Append(0).Append('\\n');\n        }\n        Console.Write(sb.ToString());\n    }\n}",hints:["Sàng Eratosthenes một lần tới r lớn nhất (≤ 10^5). Mảng bool mặc định false, nên lưu “bị gạch” thay vì “nguyên tố” để khỏi khởi tạo.","pre[x] = số số nguyên tố ≤ x; đáp án pre[r] − pre[l − 1].","Kiểm tra từng số trong đoạn bằng thử chia cho mỗi câu hỏi là quá chậm."]}},{t:"Số ước của từng số",d:"Cho n (1 ≤ n ≤ 10^6). In trên một dòng số ước dương của 1, 2, …, n, cách nhau một khoảng trắng.",tests:[{in:"12",out:"1 2 2 3 2 4 2 4 3 4 2 6"},{in:"1",out:"1"},{in:"2",out:"1 2"},{in:"100",out:"1 2 2 3 2 4 2 4 3 4 2 6 2 4 4 5 2 6 2 6 4 4 2 8 3 4 4 6 2 8 2 6 4 4 4 9 2 4 4 8 2 8 2 6 6 4 2 10 3 6 4 6 2 8 4 8 4 4 2 12 2 4 6 7 4 8 2 6 4 8 2 12 2 4 6 6 4 8 2 10 5 4 2 12 4 4 4 8 2 12 4 6 4 4 4 12 2 6 6 9"},{in:"360",out:"1 2 2 3 2 4 2 4 3 4 2 6 2 4 4 5 2 6 2 6 4 4 2 8 3 4 4 6 2 8 2 6 4 4 4 9 2 4 4 8 2 8 2 6 6 4 2 10 3 6 4 6 2 8 4 8 4 4 2 12 2 4 6 7 4 8 2 6 4 8 2 12 2 4 6 6 4 8 2 10 5 4 2 12 4 4 4 8 2 12 4 6 4 4 4 12 2 6 6 9 2 8 2 8 8 4 2 12 2 8 4 10 2 8 4 6 6 4 4 16 3 4 4 6 4 12 2 8 4 8 2 12 4 4 8 8 2 8 2 12 4 4 4 15 4 4 6 6 2 12 2 8 6 8 4 12 2 4 4 12 4 10 2 6 8 4 2 16 3 8 6 6 2 8 6 10 4 4 2 18 2 8 4 8 4 8 4 6 8 8 2 14 2 4 8 9 2 12 2 12 4 4 4 12 4 4 6 10 4 16 2 6 4 4 4 16 4 4 4 12 4 8 2 12 9 4 2 12 2 8 8 8 2 12 4 6 4 8 2 20 2 6 6 6 6 8 4 8 4 8 2 18 4 4 8 9 2 8 4 12 6 4 2 16 4 8 4 6 2 16 2 10 8 4 6 12 2 4 6 16 2 8 2 6 8 8 4 18 3 8 4 6 2 12 4 8 8 4 4 18 4 4 4 10 4 12 2 12 4 8 2 16 2 4 12 6 2 8 4 14 4 8 4 15 6 4 4 8 4 16 2 6 6 4 4 20 2 6 4 12 4 12 4 8 8 4 2 12 2 12 8 12 2 8 4 6 8 4 2 24"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> c(n + 1, 0);\n    // với mỗi d, cộng 1 cho mọi bội của d\n    for (int i = 1; i <= n; i++) cout << c[i] << (i < n ? \" \" : \"\\n\");\n    return 0;\n}",perf:{gen:n=>String(n),ns:[500,1000,2000,4000],need:"nlogn",limit:n=>5*n*Math.log2(n)+300,why:"Thử chia từng số tới căn của nó tốn O(n√n)."},py:{start:"n = int(input())\nc = [0] * (n + 1)\n# với mỗi d, cộng 1 cho mọi bội của d\nprint(*c[1:])",hints:["Đảo câu hỏi: thay vì “x có những ước nào”, hỏi “d là ước của những số nào” — mọi bội của d.","Hai vòng lặp: d từ 1 tới n, j chạy range(d, n + 1, d), tăng c[j]. Tổng số bước ≈ n ln n.","Đếm ước từng số bằng thử chia tới √x tốn khoảng n√n."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] c = new int[n + 1];\n        // với mỗi d, cộng 1 cho mọi bội của d\n        var sb = new StringBuilder();\n        for (int i = 1; i <= n; i++) sb.Append(c[i]).Append(i < n ? \" \" : \"\\n\");\n        Console.Write(sb.ToString());\n    }\n}",hints:["Đảo câu hỏi: thay vì “x có những ước nào”, hỏi “d là ước của những số nào” — mọi bội của d.","Hai vòng lặp: d từ 1 tới n, j = d, 2d, 3d, … ≤ n, tăng c[j]. Tổng số bước ≈ n ln n.","In bằng StringBuilder: n tới 10^6 số."]}},{t:"Phân tích thừa số",d:"Cho q số nguyên a_1 … a_q (q ≤ 10^5, 2 ≤ a_i ≤ 10^6). Với mỗi số in các thừa số nguyên tố theo thứ tự tăng dần, lặp lại theo số mũ, cách nhau một khoảng trắng (ví dụ 12 → 2 2 3). Đầu vào: q rồi một dòng q số. Đầu ra: q dòng.",tests:[{in:"6\n12 97 360 1000000 2 999983",out:"2 2 3\n97\n2 2 2 3 3 5\n2 2 2 2 2 2 5 5 5 5 5 5\n2\n999983"},{in:"1\n2",out:"2"},{in:"3\n1024 1001 30030",out:"2 2 2 2 2 2 2 2 2 2\n7 11 13\n2 3 5 7 11 13"},{in:"30\n540877 799918 439349 776855 776075 338109 234600 249269 311862 582256 372498 204156 388821 605110 630469 741554 914294 672326 822929 6101 319406 700433 68562 281047 303082 475350 825618 899697 169502 908804",out:"540877\n2 7 17 3361\n439349\n5 155371\n5 5 37 839\n3 43 2621\n2 2 2 3 5 5 17 23\n37 6737\n2 3 51977\n2 2 2 2 151 241\n2 3 7 7 7 181\n2 2 3 3 53 107\n3 129607\n2 5 11 5501\n7 90067\n2 11 37 911\n2 17 26891\n2 336163\n73 11273\n6101\n2 29 5507\n700433\n2 3 3 13 293\n13 13 1663\n2 13 11657\n2 3 5 5 3169\n2 3 37 3719\n3 499 601\n2 84751\n2 2 13 17477"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int q;\n    cin >> q;\n    for (int k = 0; k < q; k++) {\n        int a;\n        cin >> a;\n        // tách các thừa số nguyên tố của a\n        cout << a << \"\\n\";\n    }\n    return 0;\n}",py:{start:"q = int(input())\na = list(map(int, input().split()))\nfor x in a:\n    # tách các thừa số nguyên tố của x\n    print(x)",hints:["Thử chia p = 2, 3, … khi p · p ≤ x; chia hết thì ghi p và chia x cho p (lặp while). Cuối cùng x > 1 thì ghi x.","Gom thừa số vào list rồi \" \".join(map(str, ts)) để không thừa khoảng trắng.","Khi có rất nhiều số, sàng spf tới 10^6 nhanh hơn trên máy thật."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int q = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        foreach (int x in a)\n        {\n            // tách các thừa số nguyên tố của x\n            Console.WriteLine(x);\n        }\n    }\n}",hints:["Thử chia p = 2, 3, … khi p · p ≤ x; chia hết thì ghi p và chia x cho p (lặp while). Cuối cùng x > 1 thì ghi x.","Biến của foreach không gán lại được: chép sang biến x trước khi chia.","Khi có rất nhiều số, sàng spf tới 10^6 nhanh hơn trên máy thật."]}}]);

